/*
 * usbdisk — the two logical units of the USB mass-storage interface, between
 * the platform's USB stack (platform/stm32h743/usb.c; the simulators' model)
 * and the application (app/usb_app.c).
 *
 *   LUN 0 "CALC": the virtual drive (core/vdrive.h), always present while a
 *          computer is connected; generated by the application
 *          (usbdisk_regenerate), written into the staging buffer.
 *   LUN 1 "SD CARD": the microSD card as a raw block device (hal_sd_*), only
 *          between usbdisk_card_connect(true) and (false) (the application
 *          locks its own FAT use meanwhile); otherwise "no medium".
 *
 * Media change (SCSI, SPC-4 / SBC-3): usbdisk_media_changed(lun) makes the
 * unit report "medium not present" (sense 02/3A/00) for USBDISK_GONE_MS, then
 * one "not ready to ready change, medium may have changed" unit attention
 * (06/28/00), then ready. Hosts that keep polling TEST UNIT READY drop their
 * cached FAT and directory and read the volume again. The "not present" time
 * ends by the clock even without a poll. The CALC drive is regenerated at the
 * start of the change; while a computer has the device configured its change
 * is a reconnect instead (hal_usb_reconnect, USBDISK_RECONNECT_MS off the
 * bus), because hosts do not poll a mounted drive: macOS sends no TEST UNIT
 * READY to it, so it would keep its stale FAT and write through it.
 *
 * Called from the main loop only (the USB stack runs its callbacks from the
 * main loop, never from the interrupt handler).
 */
#ifndef USBDISK_H
#define USBDISK_H
#include <stdbool.h>
#include <stdint.h>
#include "vdrive.h"

enum { USBDISK_CALC = 0, USBDISK_CARD = 1, USBDISK_LUNS = 2 };
#define USBDISK_GONE_MS 1500u
#define USBDISK_RECONNECT_MS 500u

/* SCSI sense data of a failed command */
typedef struct {
    uint8_t key, asc, ascq;
} usbdisk_sense_t;

/* ---- the USB stack's side ---- */
bool usbdisk_ready(int lun, usbdisk_sense_t *s);              /* TEST UNIT READY */
uint32_t usbdisk_blocks(int lun);                             /* READ CAPACITY (512-byte blocks) */
bool usbdisk_writable(int lun);
/* READ10 / WRITE10 of whole 512-byte blocks: 0, or <0 with *s set */
int usbdisk_read(int lun, uint32_t lba, void *buf, uint32_t count, usbdisk_sense_t *s);
int usbdisk_write(int lun, uint32_t lba, const void *buf, uint32_t count, usbdisk_sense_t *s);
void usbdisk_eject(int lun);                                  /* START STOP UNIT, eject */
void usbdisk_inquiry(int lun, char vendor[8], char product[16], char rev[4]);
/* the host configured the device (true) or went away (false) */
void usbdisk_host(bool present);

/* ---- the application's side ---- */
/* The CALC drive: memory and the generator of its files (called with the
 * drive at every regeneration: vd_begin, vd_add_file ..., not vd_build). */
void usbdisk_init(uint8_t *mem, uint8_t *stage, uint32_t stage_bytes, void (*generate)(vdrive_t *vd));
vdrive_t *usbdisk_calc(void);
void usbdisk_media_changed(int lun);          /* regenerates LUN 0 now */
bool usbdisk_changing(int lun);               /* the unit is in its media change */
bool usbdisk_host_present(void);
uint32_t usbdisk_host_writes(void);           /* CALC sectors written since the last regeneration */
uint32_t usbdisk_last_io(void);               /* the host's last read or write of the CALC drive (ms) */
/* LUN 1: give the card to the computer (opens it: 0, or <0 no card) or take it back */
int usbdisk_card_connect(bool on);
bool usbdisk_card_connected(void);
bool usbdisk_card_ejected(void);              /* the computer ejected it (safe to take back) */

#endif
